// Второй вход (комментарий QA 13.10, фикс программиста для обоих входов): экран молитвы → ☰ → «רשימת התפילות».
// Факт 14.10: оба входа открывают «תפילות» (поле «חיפוש», «התפילות מוצגות בנוסח אשכנז שנשמר בפרופיל.», карточки), прокрутка до «שיעורי תורה»,
//   3 повторных входа — без крэша (скрины 70e8283a-ios-b20-tefilot-opened.png, -tefilot-scrolled.png, -menu-entry-opened.png).
// Все нажатия — по элементу (☰ в шапке — только по подписи, не по координатам: верхние 140 pt — зона баннеров).
import { goTab, openPrayer } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { expectAppAlive, openPrayersTab, openPrayersFromMenu, scrollPrayersToEnd, waitPrayersScreen } from '../_lib/app-1410.ts';

describe('Экран «תפילות» без крэша (#70e8283a)', () => {
  afterEach(async () => { await toHome().catch(() => {}); });

  it('PC-02a Вкладка «תפילות» открывает S-27, прокрутка до конца, 3 повторных входа — приложение живо #70e8283a @prod-safe', async () => {
    await openPrayersTab();
    await scrollPrayersToEnd('вкладка');
    for (let i = 1; i <= 3; i++) {
      await goTab('בית');
      await goTab('תפילות');
      await waitPrayersScreen(`вкладка, повторный вход ${i}`);
    }
    await expectAppAlive('после 3 входов');
  });

  it('PC-02b Экран молитвы → ☰ → «רשימת התפילות» открывает S-27, прокрутка — приложение живо #70e8283a @prod-safe', async () => {
    for (let i = 1; i <= 3; i++) {
      await toHome();
      await openPrayer('mincha_ashkenaz', 'מנחה');      // без deep link — через вкладку «תפילות» (тоже проверка входа)
      await openPrayersFromMenu();
      if (i === 1) await scrollPrayersToEnd('☰ → «רשימת התפילות»');
    }
    await expectAppAlive('после 3 входов через ☰');
  });
});
